const CLONE_DEFAULTS={copyPose:true,copyCamera:true,copyStyle:false,copyOutfit:false,copyExpression:false,copyBackground:false,referenceColors:false,autoRatio:true,fidelity:'strict',ratio:'3:4',text:''};
const RATIOS=['1:1','9:16','16:9','4:3','3:4'];
function nearestRatio(width,height){if(!Number.isFinite(width)||!Number.isFinite(height)||width<=0||height<=0)throw Error('Không đọc được kích thước ảnh mẫu');const value=width/height;return RATIOS.reduce((best,r)=>{const[a,b]=r.split(':').map(Number),[c,d]=best.split(':').map(Number);return Math.abs(Math.log(value/(a/b)))<Math.abs(Math.log(value/(c/d)))?r:best},RATIOS[0])}
function buildCloneBatch({base,refs,settings={},make,edge}){if(!base)throw Error('Chọn ảnh nhân vật gốc');if(!Array.isArray(refs)||!refs.length)throw Error('Chọn ít nhất một ảnh mẫu');const unique=[...new Map(refs.map(r=>[r.tag,r])).values()];if(unique.some(r=>!r.tag||r.tag===base))throw Error('Bộ ảnh mẫu cần ảnh khác với ảnh nhân vật gốc');const cfg={...CLONE_DEFAULTS,...settings};if(!RATIOS.includes(cfg.ratio))throw Error('Tỉ lệ không hợp lệ');if(![cfg.copyPose,cfg.copyCamera,cfg.copyStyle,cfg.copyOutfit,cfg.copyExpression,cfg.copyBackground,cfg.referenceColors,cfg.autoRatio].some(Boolean))throw Error('Bật ít nhất một thuộc tính cần lấy từ ảnh mẫu');const source=make('source',0,90,{label:'MASTER · Nhân vật & trang phục gốc',refTag:base}),nodes=[source],edges=[];unique.forEach((r,i)=>{const ratio=cfg.autoRatio?nearestRatio(r.width,r.height):cfg.ratio,b=make('board',380,i*560,{label:String(i+1).padStart(2,'0')+' · Ref @'+r.tag});b.style={width:1100,height:520};nodes.push(b);const guide=make('source',40,90,{label:'Mẫu '+(i+1),refTag:r.tag}),clone=make('clone',400,90,{...cfg,kind:'clone',ratio,referenceAspect:r.width&&r.height?r.width+' × '+r.height:'',label:'Tái hiện '+(i+1)+' · '+ratio}),out=make('output',760,90,{label:'Kết quả '+(i+1)});for(const n of [guide,clone,out]){n.parentId=b.id;nodes.push(n)}edges.push(edge(source,clone),edge(guide,clone,'guide'),edge(clone,out))});return {reviewBeforeNext:true,nodes,edges,viewport:{x:50,y:60,zoom:.65}}}
module.exports={CLONE_DEFAULTS,RATIOS,nearestRatio,buildCloneBatch};
